# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">EVİN BÖLÜMLERİ (أَقْسَامُ الْبَيْتِ) VE TEMEL KELİMELER</text>\n  <rect x="20" y="45" width="210" height="95" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">غُرْفَةُ الْجُلُوسِ</text>\n  <text x="125" y="88" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e3a8a">Oturma Odası / Salon</text>\n  <text x="125" y="110" text-anchor="middle" font-size="10.5" fill="#3b82f6">أَرِيكَةٌ (Koltuk) · تِلْفَازٌ (TV)</text>\n  <text x="125" y="126" text-anchor="middle" font-size="10.5" fill="#3b82f6">سَجَّادَةٌ (Halı) · طَاوِلَةٌ (Masa)</text>\n  <rect x="245" y="45" width="210" height="95" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">غُرْفَةُ النَّوْمِ</text>\n  <text x="350" y="88" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">Yatak Odası</text>\n  <text x="350" y="110" text-anchor="middle" font-size="10.5" fill="#166534">سَرِيرٌ (Yatak) · خِزَانَةٌ (Dolap)</text>\n  <text x="350" y="126" text-anchor="middle" font-size="10.5" fill="#166534">وِسَادَةٌ (Yastık) · مِرْآةٌ (Ayna)</text>\n  <rect x="470" y="45" width="210" height="95" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">الْمَطْبَخُ</text>\n  <text x="575" y="88" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#78350f">Mutfak</text>\n  <text x="575" y="110" text-anchor="middle" font-size="10.5" fill="#92400e">ثَلَّاجَةٌ (Buzdolabı) · فُرْنٌ (Fırın)</text>\n  <text x="575" y="126" text-anchor="middle" font-size="10.5" fill="#92400e">كُرْسِيٌّ (Sandalye)</text>\n  <rect x="20" y="152" width="210" height="92" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="125" y="174" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">غُرْفَةُ الدِّرَاسَةِ / الْأَطْفَالِ</text>\n  <text x="125" y="194" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#581c87">Çalışma / Çocuk Odası</text>\n  <text x="125" y="216" text-anchor="middle" font-size="10.5" fill="#6b21a8">مَكْتَبٌ (Çalışma Masası)</text>\n  <text x="125" y="232" text-anchor="middle" font-size="10.5" fill="#6b21a8">حَاسُوبٌ (Bilgisayar)</text>\n  <rect x="245" y="152" width="210" height="92" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="350" y="174" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">الْحَمَّامُ وَالْمَدْخَلُ</text>\n  <text x="350" y="194" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#155e75">Banyo ve Antre (Giriş)</text>\n  <text x="350" y="216" text-anchor="middle" font-size="10.5" fill="#0e7490">مِغْسَلَةٌ (Lavabo) · صَابُونٌ (Sabun)</text>\n  <text x="350" y="232" text-anchor="middle" font-size="10.5" fill="#0e7490">بَابٌ (Kapı) · نَافِذَةٌ (Pencere)</text>\n  <rect x="470" y="152" width="210" height="92" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="575" y="174" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">الْحَدِيقَةُ وَالشُّرْفَةُ</text>\n  <text x="575" y="194" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#7f1d1d">Bahçe ve Balkon</text>\n  <text x="575" y="216" text-anchor="middle" font-size="10.5" fill="#991b1b">شَجَرَةٌ (Ağaç) · أَزْهَارٌ (Çiçekler)</text>\n  <text x="575" y="232" text-anchor="middle" font-size="10.5" fill="#991b1b">بَيْتٌ كَبِيرٌ وَجَمِيلٌ (Büyük ve Güzel Ev)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HARF-İ CERLER VE MEKÂN ZARFLARI (حُرُوفُ الْجَرِّ وَظُرُوفُ الْمَكَانِ)</text>\n  <rect x="25" y="45" width="310" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">YER BİLDİREN EDAT VE ZARFLAR</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#1e3a8a">• فِي (fî): içinde / -de, -da</text>\n  <text x="42" y="120" font-size="11.5" font-weight="bold" fill="#1e3a8a">• عَلَى (alâ) / فَوْقَ (fevka): üstünde, üzerinde</text>\n  <text x="42" y="144" font-size="11.5" font-weight="bold" fill="#1e3a8a">• تَحْتَ (tahte): altında</text>\n  <text x="42" y="168" font-size="11.5" font-weight="bold" fill="#1e3a8a">• أَمَامَ (emâme): önünde</text>\n  <text x="42" y="192" font-size="11.5" font-weight="bold" fill="#1e3a8a">• خَلْفَ (halfe) / وَرَاءَ (verâe): arkasında</text>\n  <text x="42" y="216" font-size="11.5" font-weight="bold" fill="#1e3a8a">• بِجَانِبِ (bicânibi): yanında, bitişiğinde</text>\n  <rect x="355" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="515" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">أَيْنَ ...؟ (NEREDE?) ÖRNEK CÜMLELERİ</text>\n  <text x="372" y="96" font-size="11" font-weight="bold" fill="#14532d">• الْكِتَابُ عَلَى الطَّاوِلَةِ.</text>\n  <text x="380" y="114" font-size="10.5" fill="#166534">(Kitap masanın üzerindedir.)</text>\n  <text x="372" y="138" font-size="11" font-weight="bold" fill="#14532d">• الْحَقِيبَةُ تَحْتَ الْمَكْتَبِ.</text>\n  <text x="380" y="156" font-size="10.5" fill="#166534">(Çanta sıranın/masanın altındadır.)</text>\n  <text x="372" y="180" font-size="11" font-weight="bold" fill="#14532d">• الْحَدِيقَةُ أَمَامَ الْبَيْتِ.</text>\n  <text x="380" y="198" font-size="10.5" fill="#166534">(Bahçe evin önündedir.)</text>\n  <text x="372" y="220" font-size="10.5" font-weight="bold" fill="#b91c1c">Kural: Bu edatlardan sonra gelen isim kesralı (-i) okunur!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ŞİBİH CÜMLELİ HABERÎ İSİM CÜMLELERİ (VARDIR KALIPLARI)</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">1. BELİRLİ ÖZNE İLE BAŞLAYAN CÜMLE</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#78350f">Yapı: [El-Mübteda (Belirli)] + [Şibih Cümle Haber]</text>\n  <text x="42" y="124" font-size="12" font-weight="bold" fill="#b45309">التِّلْفَازُ فِي غُرْفَةِ الْجُلُوسِ.</text>\n  <text x="42" y="144" font-size="11" fill="#78350f">Anlamı: Televizyon oturma odasındadır.</text>\n  <text x="42" y="172" font-size="12" font-weight="bold" fill="#b45309">الثَّلَّاجَةُ فِي الْمَطْبَخِ.</text>\n  <text x="42" y="192" font-size="11" fill="#78350f">Anlamı: Buzdolabı mutfaktadır.</text>\n  <text x="42" y="220" font-size="10.5" fill="#92400e">Not: Mübteda başında "ال" (el) takısı vardır.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">2. ÖNE GEÇMİŞ HABER ("...DE ... VARDIR")</text>\n  <text x="377" y="96" font-size="11.5" font-weight="bold" fill="#581c87">Yapı: [Mukaddem Haber] + [Muahhar Mübteda (Nekre)]</text>\n  <text x="377" y="124" font-size="12" font-weight="bold" fill="#7e22ce">فِي الْبَيْتِ حَدِيقَةٌ وَاسِعَةٌ.</text>\n  <text x="377" y="144" font-size="11" fill="#581c87">Anlamı: Evde geniş bir bahçe vardır.</text>\n  <text x="377" y="172" font-size="12" font-weight="bold" fill="#7e22ce">فِي الصَّفِّ سَبُّورَةٌ وَطَاوِلَاتٌ.</text>\n  <text x="377" y="192" font-size="11" fill="#581c87">Anlamı: Sınıfta bir yazı tahtası ve masalar vardır.</text>\n  <text x="377" y="220" font-size="10.5" fill="#6b21a8">Not: Sona kalan mübteda tenvinli (belirsiz) gelir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
